[metadata]
license_files = LICENSE
[tox]
envlist = py37,py38,py39,py310,py311,py312,py313,py314,pypy3
requires = tox-uv

[testenv]
changedir = .tox
dependency_groups = dev
commands = pytest --doctest-modules {env_site_packages_dir}/boltons {tox_root}/tests {posargs}
43:    "pytest>=7,<8; python_version < '3.8'",
44:    "pytest>=8; python_version >= '3.8'",
45-]
46-
47:[tool.pytest.ini_options]
48-doctest_optionflags = [
49-    "ALLOW_UNICODE",
50-    "ELLIPSIS",
51-    "IGNORE_EXCEPTION_DETAIL",
52-    "NORMALIZE_WHITESPACE",
53-]
54-
55-[build-system]
        include:
          - { name: Linux, python: "3.14", os: ubuntu-latest, tox: py314 }
          - { name: Windows, python: "3.14", os: windows-latest, tox: py314 }
          - { name: Mac, python: "3.14", os: macos-latest, tox: py314 }
          - { name: "3.13", python: "3.13", os: ubuntu-latest, tox: py313 }
          - { name: "3.12", python: "3.12", os: ubuntu-latest, tox: py312 }
          - { name: "3.11", python: "3.11", os: ubuntu-latest, tox: py311 }
          - { name: "3.10", python: "3.10", os: ubuntu-latest, tox: py310 }
          - { name: "3.9", python: "3.9", os: ubuntu-latest, tox: py39 }
          - { name: "3.8", python: "3.8", os: ubuntu-latest, tox: py38 }
          - { name: "3.7", python: "3.7", os: ubuntu-22.04, tox: py37 }
          - { name: "PyPy3", python: "pypy-3.9", os: ubuntu-latest, tox: pypy3 }
    steps:
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7.0.0
      - uses: astral-sh/setup-uv@11f9893b081a58869d3b5fccaea48c9e9e46f990 # v8.3.2
      - uses: actions/setup-python@ece7cb06caefa5fff74198d8649806c4678c61a1 # v6.3.0
        with:
          python-version: ${{ matrix.python }}
          allow-prereleases: true
      - run: uvx --with tox-uv tox -e ${{ matrix.tox }}
pytest 8.3.4

